  fresh_frame H LF 0 ff fp ->
  rw_cells bsegs m ff [CB 32 hj; C8 (wz M); C1 (b8 1); CB 15 hk; C8 fpw] ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880) [CB 4 sha; C1 (b8 0); C1 (b8 0); CB 2 shb] ->
  APMutex m M EBUSY -> M mod 8 = 0 -> 0 < M ->
  stk bsegs m lo (bv_unsigned sp) -> lo + AULOCK_DTOR_STACK <= bv_unsigned sp -> aceil <= lo ->
  (M + 40 <= lo \/ bv_unsigned sp <= M) ->
  bv_unsigned ra mod 2 = 0 -> mem_inv bsegs m -> ACONST m ->
  evt bsegs (mtx_unlock_post ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc M lo m)
