Definition fb_consume_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (a k lo : Z) (FB : fbv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 a0 a1 a2 a3 a4 a5 a6 a7 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (a + 8, a + 24)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' a (FlatBufCells (fb_consume FB k)).

Lemma fb_consume_spec : forall (a k lo : Z) (FB : fbv)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem),
  rw_cells bsegs m a (FlatBufCells FB) -> aapp a 48 -> accessible m a 24 -> a mod 8 = 0 ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_last FB <= fb_end FB -> fb_end FB <= aceil ->
  (k < fb_size FB -> 0 < fb_begin FB) -> 0 <= k < 2^64 ->
  (a + 48 <= lo \/ bv_unsigned sp <= a) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + AFB_CONSUME_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 -> mem_inv bsegs m -> ACONST m ->
  evt bsegs (fb_consume_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t1 t2 t3 t4 t5 t6 F fc a k lo FB m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz a) (wz k) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_FB_CONSUME) fc None m (seg_rom bsegs)).
